VERTEX_SHADER = '`\n  attribute vec3 instancePosition;\n  uniform float uTime;\n  uniform float uSpeed;\n  uniform float uBend;\n\n  varying float vElevation;\n  varying float vSide;\n  varying vec3  vNormal;\n  varying vec3  vWorldPos;\n\n  float hash(vec2 p) {\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\n  }\n  float noise(vec2 p) {\n    vec2 i = floor(p);\n    vec2 f = fract(p);\n    f = f * f * (3.0 - 2.0 * f);\n    float a = hash(i);\n    float b = hash(i + vec2(1.0, 0.0));\n    float c = hash(i + vec2(0.0, 1.0));\n    float d = hash(i + vec2(1.0, 1.0));\n    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);\n  }\n\n  void main() {\n    vec3 localPos = position;\n    float y = localPos.y;\n\n    float n = noise(instancePosition.xz * 0.8 + uTime * uSpeed * 0.4);\n    float wind = n * 2.0 - 1.0;\n    float H2 = 0.1225 * 0.1225;\n    float bend = uBend * wind * (y * y) / H2;\n    localPos.x += bend;\n\n    float swayN = noise(instancePosition.xz * 1.6 + uTime * uSpeed * 0.2 + 100.0);\n    float sway = swayN * 2.0 - 1.0;\n    localPos.z += sway * 0.02 * (y / 0.35);\n\n    vec3 camPos = inverse(viewMatrix)[3].xyz;\n    vec2 toCam = normalize(camPos.xz - instancePosition.xz);\n    float angle = atan(toCam.y, toCam.x);\n    float c = cos(angle);\n    float s = sin(angle);\n    mat3 rot = mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c);\n    localPos = rot * localPos;\n\n    vec4 worldPos = modelMatrix * vec4(instancePosition, 0.0) + vec4(localPos, 0.0);\n    vWorldPos   = worldPos.xyz;\n    vElevation  = y / 0.35;\n    vSide       = localPos.z / 0.04;\n\n    float eps = 0.001;\n    vec3 px = localPos; px.x += eps;\n    vec3 worldP  = modelMatrix * vec4(instancePosition, 0.0) + vec4(localPos, 0.0);\n    vec3 worldPx = modelMatrix * vec4(instancePosition, 0.0) + vec4(px, 0.0);\n    vec3 dx = worldPx - worldP;\n    vec3 dy = normalize(worldPos + vec3(0.0, eps, 0.0) - worldPos);\n    vNormal = normalize(cross(dx, dy));\n\n    gl_Position = projectionMatrix * viewMatrix * worldPos;\n  }\n`'
FRAGMENT_SHADER = '`\n  uniform vec3 uBaseColor;\n  uniform vec3 uTipColor;\n  uniform vec3 uLightDir;\n  uniform vec3 uLightColor;\n  uniform float uAmbient;\n\n  varying float vElevation;\n  varying float vSide;\n  varying vec3  vNormal;\n  varying vec3  vWorldPos;\n\n  void main() {\n    float grad = smoothstep(0.0, 1.0, vElevation);\n    vec3 color = mix(uBaseColor, uTipColor, grad);\n    float edge = 1.0 - abs(vSide);\n    color *= 0.85 + 0.15 * edge;\n    vec3 n = normalize(vNormal);\n    float diff = max(0.0, dot(n, normalize(uLightDir)));\n    float lighting = uAmbient + (1.0 - uAmbient) * diff;\n    color *= lighting * uLightColor;\n    gl_FragColor = vec4(color, 1.0);\n  }\n`'
